import{bV as s,aL as e,u as n,G as o}from"./chunks/framework.BfzMay2U.js";const b=JSON.parse('{"title":"自我介绍模板","description":"","frontmatter":{"title":"自我介绍模板","date":"2026-09-29T12:00:00.000Z","categories":["面试，PHP"],"tags":["自我介绍，求职技巧，简历"],"sidebarSort":8},"headers":[],"relativePath":"php/soft/self-introduction-templates.md","filePath":"php/soft/self-introduction-templates.md"}'),l={name:"php/soft/self-introduction-templates.md"};function t(i,a,r,p,u,c){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="自我介绍模板-编号-81-100" tabindex="-1">自我介绍模板（编号 81-100） <a class="header-anchor" href="#自我介绍模板-编号-81-100" aria-label="Permalink to &quot;自我介绍模板（编号 81-100）&quot;">​</a></h1><h2 id="模板一-3-年经验-laravel-后端开发" tabindex="-1">模板一：3 年经验 Laravel 后端开发 <a class="header-anchor" href="#模板一-3-年经验-laravel-后端开发" aria-label="Permalink to &quot;模板一：3 年经验 Laravel 后端开发&quot;">​</a></h2><h3 id="⏱-时长-2-分钟" tabindex="-1">⏱ 时长：2 分钟 <a class="header-anchor" href="#⏱-时长-2-分钟" aria-label="Permalink to &quot;⏱ 时长：2 分钟&quot;">​</a></h3><p><strong>开场（15 秒）</strong>：</p><blockquote><p>&quot;面试官好，我叫 XXX，有 3 年 PHP 开发经验，主要使用 Laravel 框架进行企业级应用开发。&quot;</p></blockquote><p><strong>技术栈（30 秒）</strong>：</p><blockquote><p>&quot;我熟练掌握 Laravel 8/9、MySQL 数据库优化、Redis 缓存策略，以及 RESTful API 设计。在上一家公司，我主导了 MES 系统与 ERP 的对接开发，实现了订单自动同步和生产数据回传。&quot;</p></blockquote><p><strong>项目经验（45 秒）</strong>：</p><blockquote><p>&quot;最近负责的项目是一个医疗器械电子批记录系统（E-DHR），需要符合 FDA 21 CFR Part 11 合规要求。我设计了完整的审计追踪机制，确保所有操作可追溯、不可篡改。通过引入消息队列异步处理大批量数据导入，将响应时间从 10 秒降低到 2 秒以内。&quot;</p></blockquote><p><strong>软技能（20 秒）</strong>：</p><blockquote><p>&quot;除了技术开发，我还习惯编写详细的技术文档和接口说明，帮助团队成员快速上手。&quot;</p></blockquote><p><strong>结尾（10 秒）</strong>：</p><blockquote><p>&quot;希望能加入贵公司，为工厂数字化项目贡献力量。谢谢！&quot;</p></blockquote><hr><h2 id="模板二-5-年经验全栈开发-含-uniapp" tabindex="-1">模板二：5 年经验全栈开发（含 UniApp） <a class="header-anchor" href="#模板二-5-年经验全栈开发-含-uniapp" aria-label="Permalink to &quot;模板二：5 年经验全栈开发（含 UniApp）&quot;">​</a></h2><h3 id="⏱-时长-3-分钟" tabindex="-1">⏱ 时长：3 分钟 <a class="header-anchor" href="#⏱-时长-3-分钟" aria-label="Permalink to &quot;⏱ 时长：3 分钟&quot;">​</a></h3><p><strong>个人背景（20 秒）</strong>：</p><blockquote><p>&quot;您好，我是 XXX，从事 PHP 全栈开发 5 年，专注于制造行业信息化系统建设。&quot;</p></blockquote><p><strong>核心能力（50 秒）</strong>：</p><blockquote><p>&quot;技术方面：精通 Laravel + MySQL + Vue3 前后端分离架构，熟练使用 UniApp 开发微信小程序和 APP。最近开发了工厂移动端报工系统，支持扫码、GPS 定位、离线存储等功能。&quot;</p></blockquote><p><strong>系统集成经验（60 秒）</strong>：</p><blockquote><p>&quot;我有丰富的系统集成经验，包括：</p><ul><li>ERP（SAP/金蝶/用友）订单与物料主数据同步</li><li>OA（泛微/致远）审批流集成</li><li>MES 设备数据采集与生产报工</li><li>WMS 仓储管理系统对接</li></ul><p>曾经解决过一个棘手问题：MES 设备每秒产生大量传感器数据，通过 Redis Stream + 批量写入优化，解决了数据库性能瓶颈。&quot;</p></blockquote><p><strong>项目管理（25 秒）</strong>：</p><blockquote><p>&quot;作为技术负责人，我带领 3 人团队完成了整个项目的开发与上线，熟悉敏捷开发流程，能独立承担需求分析、技术方案、代码实现和运维支持。&quot;</p></blockquote><p><strong>期望匹配（15 秒）</strong>：</p><blockquote><p>&quot;这个岗位需要的技能我都具备，也很期待参与贵公司的智慧工厂项目。&quot;</p></blockquote><hr><h2 id="模板三-转行-初级开发者-1-2-年经验" tabindex="-1">模板三：转行/初级开发者（1-2 年经验） <a class="header-anchor" href="#模板三-转行-初级开发者-1-2-年经验" aria-label="Permalink to &quot;模板三：转行/初级开发者（1-2 年经验）&quot;">​</a></h2><h3 id="⏱-时长-1-5-分钟" tabindex="-1">⏱ 时长：1.5 分钟 <a class="header-anchor" href="#⏱-时长-1-5-分钟" aria-label="Permalink to &quot;⏱ 时长：1.5 分钟&quot;">​</a></h3><p><strong>学习经历（25 秒）</strong>：</p><blockquote><p>&quot;面试官好，我叫 XXX，本科毕业于 XX 大学计算机专业。过去 2 年我一直在 Laravel 项目一线开发。&quot;</p></blockquote><p><strong>技术成长（40 秒）</strong>：</p><blockquote><p>&quot;我从零开始自学 PHP，通过实战项目逐步掌握了：</p><ul><li>Laravel 核心机制（依赖注入、中间件、事件系统）</li><li>MySQL 索引优化（EXPLAIN 分析慢查询）</li><li>Redis 缓存设计与分布式锁实现</li><li>Linux 部署和 Nginx 配置</li></ul><p>GitHub 上有一个自己写的轻量级工作流引擎，展示了我的主动学习能力。&quot;</p></blockquote><p><strong>项目实践（35 秒）</strong>：</p><blockquote><p>&quot;最近在一家制造业公司实习，参与了车间报工系统的开发。虽然只是部分功能，但我独立完成了：</p><ul><li>报工接口的 CRUD 和操作日志记录</li><li>工单状态机的设计与实现</li><li>简单的权限控制逻辑</li></ul><p>这段经历让我理解了业务需求转技术的流程。&quot;</p></blockquote><p><strong>职业目标（20 秒）</strong>：</p><blockquote><p>&quot;我希望在这个方向深耕，未来成为智能制造领域的技术专家。感谢机会！&quot;</p></blockquote><hr><h2 id="模板四-技术经理-team-leader" tabindex="-1">模板四：技术经理/Team Leader <a class="header-anchor" href="#模板四-技术经理-team-leader" aria-label="Permalink to &quot;模板四：技术经理/Team Leader&quot;">​</a></h2><h3 id="⏱-时长-3-分钟-1" tabindex="-1">⏱ 时长：3 分钟 <a class="header-anchor" href="#⏱-时长-3-分钟-1" aria-label="Permalink to &quot;⏱ 时长：3 分钟&quot;">​</a></h3><p><strong>管理职责（30 秒）</strong>：</p><blockquote><p>&quot;您好，我是 XXX，有 6 年 PHP 开发经验和 2 年团队管理经验。目前担任技术主管，管理 8 人研发团队。&quot;</p></blockquote><p><strong>技术架构能力（60 秒）</strong>：</p><blockquote><p>&quot;我擅长技术选型和架构设计，曾主导过：</p><ul><li><strong>多租户 SaaS 平台</strong>：基于 Laravel 构建，支持 50+ 企业客户，日均订单 10 万 +</li><li><strong>工业物联网平台</strong>：处理设备数据接入、实时告警、可视化看板</li><li><strong>微服务改造</strong>：将单体应用拆分为 6 个服务，提升可扩展性和维护性</li></ul><p>技术决策注重平衡：稳定性优先、成本可控、迭代高效。&quot;</p></blockquote><p><strong>团队建设（45 秒）</strong>：</p><blockquote><p>&quot;管理方面：</p><ul><li>制定代码规范、Code Review 机制、CI/CD流水线</li><li>组织内部技术分享，提升团队整体能力</li><li>培养 junior 工程师，2 人晋升为中级</li><li>与产品、测试、运维紧密配合，保证交付质量</li></ul><p>我们团队的 bug 率降低了 40%，上线准时率达到 95%。&quot;</p></blockquote><p><strong>业务理解（30 秒）</strong>：</p><blockquote><p>&quot;我深刻理解制造业痛点：</p><ul><li>系统必须稳定可靠（停机意味着停工）</li><li>数据准确性至关重要（库存不准会误产）</li><li>需要快速响应业务变更（工艺调整频繁）</li></ul><p>这些认知来自一线开发的实际经验。&quot;</p></blockquote><p><strong>合作意愿（15 秒）</strong>：</p><blockquote><p>&quot;希望能为贵公司的数字化转型贡献价值。谢谢！&quot;</p></blockquote><hr><h2 id="模板五-医疗器械行业专精" tabindex="-1">模板五：医疗器械行业专精 <a class="header-anchor" href="#模板五-医疗器械行业专精" aria-label="Permalink to &quot;模板五：医疗器械行业专精&quot;">​</a></h2><h3 id="⏱-时长-2-5-分钟" tabindex="-1">⏱ 时长：2.5 分钟 <a class="header-anchor" href="#⏱-时长-2-5-分钟" aria-label="Permalink to &quot;⏱ 时长：2.5 分钟&quot;">​</a></h3><p><strong>行业背景（20 秒）</strong>：</p><blockquote><p>&quot;面试官好，我有 4 年制药/医疗器械行业软件开发经验。&quot;</p></blockquote><p><strong>合规经验（70 秒）</strong>：</p><blockquote><p>&quot;<strong>FDA 21 CFR Part 11 合规开发</strong>是我最核心的竞争力：</p><ul><li><strong>电子签名</strong>：实现了两级密码验证 + 生物识别</li><li><strong>审计追踪</strong>：所有数据修改都有 old/new values 对比</li><li><strong>权限控制</strong>：RBAC+ 字段级权限（如只能看不能改）</li><li><strong>数据安全</strong>：操作日志异地备份 + 防删除</li><li><strong>验证文档</strong>：完成 IQ/OQ/PQ 验证测试</li></ul><p>参与的 E-DHR 系统成功通过了药监局飞检。&quot;</p></blockquote><p><strong>系统设计（40 秒）</strong>：</p><blockquote><p>&quot;针对 GMP 要求，我设计了：</p><ul><li><strong>防错机制</strong>：扫描物料条码核对有效期和批次</li><li><strong>双人复核</strong>：关键操作需双人确认</li><li><strong>电子批记录</strong>：完整的生产过程记录，可追溯至原料批次</li><li><strong>偏差管理</strong>：异常情况的报告和处理流程</li></ul><p>这些设计确保了产品质量和安全。&quot;</p></blockquote><p><strong>技术栈匹配（20 秒）</strong>：</p><blockquote><p>&quot;同时我也掌握 Laravel、MySQL、UniApp等通用技术，可以快速上手各类开发任务。&quot;</p></blockquote><p><strong>总结（20 秒）</strong>：</p><blockquote><p>&quot;我认为这个岗位要求不仅需要技术，更需要对医药行业的理解。这是我的优势所在。谢谢！&quot;</p></blockquote><hr><h2 id="常见追问及应对策略" tabindex="-1">常见追问及应对策略 <a class="header-anchor" href="#常见追问及应对策略" aria-label="Permalink to &quot;常见追问及应对策略&quot;">​</a></h2><h3 id="q1-你的项目中最难的技术点是什么" tabindex="-1">Q1: 你的项目中最难的技术点是什么？ <a class="header-anchor" href="#q1-你的项目中最难的技术点是什么" aria-label="Permalink to &quot;Q1: 你的项目中最难的技术点是什么？&quot;">​</a></h3><p><strong>错误回答</strong>:</p><blockquote><p>&quot;就是些增删改查，没啥难的。&quot; ❌</p></blockquote><p><strong>正确示范</strong>:</p><div class="language-php vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;最难的是工单进度实时更新。初期用轮询方式，每 5 秒刷新一次，发现：</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1. 占用带宽大（100 个工位并发时延迟明显）</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2. 服务器压力高（CPU 峰值达 80%）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">最终采用 WebSocket + 心跳检测方案：</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- 建立长连接，实时推送进度变更</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- 客户端定期发送心跳（30 秒）</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- 断线自动重连 + 状态恢复</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">- 性能优化：只推送变更的数据字段</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">结果：CPU 下降到 15%，延迟降低到毫秒级。&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ✅</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="q2-为什么离开上家公司" tabindex="-1">Q2: 为什么离开上家公司？ <a class="header-anchor" href="#q2-为什么离开上家公司" aria-label="Permalink to &quot;Q2: 为什么离开上家公司？&quot;">​</a></h3><p><strong>错误回答</strong>:</p><blockquote><p>&quot;老板太抠、加班太多、同事关系复杂...&quot; ❌</p></blockquote><p><strong>正确示范</strong>:</p><blockquote><p>&quot;主要是职业规划考虑：</p><ol><li><strong>技术深度</strong>：现在的工作偏 CRUD，想挑战更复杂的系统架构</li><li><strong>业务领域</strong>：看好智能制造行业前景，希望深耕</li><li><strong>发展空间</strong>：当前公司规模较小，技术晋升路径有限</li></ol><p>贵公司在这方面很出色，比如 [提及对方公司亮点]，所以我选择投递。&quot; ✅</p></blockquote><h3 id="q3-你期望薪资是多少" tabindex="-1">Q3: 你期望薪资是多少？ <a class="header-anchor" href="#q3-你期望薪资是多少" aria-label="Permalink to &quot;Q3: 你期望薪资是多少？&quot;">​</a></h3><p><strong>错误回答</strong>:</p><blockquote><p>&quot;多少都行&quot; / &quot;随便给&quot; / 过早说具体数字 ❌</p></blockquote><p><strong>正确示范</strong>:</p><blockquote><p>&quot;我先了解一下这个岗位的薪资范围？另外，考虑到我带来的：</p><ul><li>Laravel + 系统集成经验可直接复用</li><li>MES/ERP对接成功案例</li><li>能够独立承担模块开发和带新人</li></ul><p>我相信公司会有合理的评估。我更看重长期发展机会。&quot; ✅</p></blockquote><h3 id="q4-你有什么要问我们的吗" tabindex="-1">Q4: 你有什么要问我们的吗？ <a class="header-anchor" href="#q4-你有什么要问我们的吗" aria-label="Permalink to &quot;Q4: 你有什么要问我们的吗？&quot;">​</a></h3><p><strong>准备 3-5 个问题</strong>：</p><p>✅ <strong>好的问题</strong>：</p><ul><li>&quot;团队当前的技术栈和架构是怎样的？&quot;</li><li>&quot;这个岗位面临的最大技术挑战是什么？&quot;</li><li>&quot;公司是否有智能制造相关的战略规划？&quot;</li><li>&quot;对新员工有哪些培训和发展支持？&quot;</li><li>&quot;团队的研发流程和工具链如何？&quot;</li></ul><p>❌ <strong>避免的问题</strong>：</p><ul><li>&quot;加班多吗？&quot;（太早问显得怕累）</li><li>&quot;工资多少？五险一金怎么交？&quot;（HR 面再问）</li><li>&quot;这个岗位是做什么的？&quot;（没做功课）</li></ul><hr><h2 id="自我介绍万能公式" tabindex="-1">自我介绍万能公式 <a class="header-anchor" href="#自我介绍万能公式" aria-label="Permalink to &quot;自我介绍万能公式&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1️⃣ 我是谁（基本信息）</span></span>
<span class="line"><span>   👉 姓名 + 工作年限 + 核心技术栈</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2️⃣ 我能做什么（核心竞争力）</span></span>
<span class="line"><span>   👉 3 个关键技术 + 1-2 个代表性项目</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3️⃣ 我做过什么（成果量化）</span></span>
<span class="line"><span>   👉 业绩数据、技术难点攻克、效率提升</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4️⃣ 我为何匹配（关联岗位）</span></span>
<span class="line"><span>   👉 对照 JD 要求，强调优势</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5️⃣ 我的期望（职业目标）</span></span>
<span class="line"><span>   👉 短期目标 + 对公司认可</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p><strong>示例填充</strong>：</p><blockquote><p>&quot;我叫张三（1️⃣），3 年 PHP/Laravel开发经验，擅长系统接口开发和数据库优化（2️⃣）。最近负责 MES 系统对接ERP，通过引入队列异步处理，将订单同步时间从 10 秒降到 2 秒（3️⃣）。我看到 JD 要求 Laravel+ 系统集成经验，这和我非常匹配（4️⃣）。希望在贵公司持续深耕制造业信息化领域（5️⃣）。&quot;</p></blockquote><hr><h2 id="不同场景调整策略" tabindex="-1">不同场景调整策略 <a class="header-anchor" href="#不同场景调整策略" aria-label="Permalink to &quot;不同场景调整策略&quot;">​</a></h2><h3 id="📍-初创公司-→-突出全能-快速上手" tabindex="-1">📍 初创公司 → 突出全能 + 快速上手 <a class="header-anchor" href="#📍-初创公司-→-突出全能-快速上手" aria-label="Permalink to &quot;📍 初创公司 → 突出全能 + 快速上手&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我一个人就能搞定前后端，还能独立部署上线。</span></span>
<span class="line"><span>上周刚帮客户修复了一个线上紧急 Bug，从排查到解决用了不到 30 分钟。&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="📍-大公司-→-突出规范-团队协作" tabindex="-1">📍 大公司 → 突出规范 + 团队协作 <a class="header-anchor" href="#📍-大公司-→-突出规范-团队协作" aria-label="Permalink to &quot;📍 大公司 → 突出规范 + 团队协作&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我熟悉大型项目的开发流程，代码风格符合 PSR 标准，</span></span>
<span class="line"><span>习惯 Code Review，文档编写规范，能快速融入团队。&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="📍-外包公司-→-突出适应性-交付能力" tabindex="-1">📍 外包公司 → 突出适应性 + 交付能力 <a class="header-anchor" href="#📍-外包公司-→-突出适应性-交付能力" aria-label="Permalink to &quot;📍 外包公司 → 突出适应性 + 交付能力&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我在外包公司锻炼了快速学习新技术的能力，</span></span>
<span class="line"><span>半年内接触过 ERP/MES/WMS 三个不同系统，都能按时交付。&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="📍-甲方自用-it-→-突出业务理解-稳定性" tabindex="-1">📍 甲方自用 IT → 突出业务理解 + 稳定性 <a class="header-anchor" href="#📍-甲方自用-it-→-突出业务理解-稳定性" aria-label="Permalink to &quot;📍 甲方自用 IT → 突出业务理解 + 稳定性&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;我做的系统都是直接服务生产的，对&#39;系统必须稳定&#39;有深刻体会，</span></span>
<span class="line"><span>不会为了炫技而牺牲可用性。&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="加分项-可插入任意模板" tabindex="-1">加分项（可插入任意模板） <a class="header-anchor" href="#加分项-可插入任意模板" aria-label="Permalink to &quot;加分项（可插入任意模板）&quot;">​</a></h2><h3 id="💡-技术热情" tabindex="-1">💡 技术热情 <a class="header-anchor" href="#💡-技术热情" aria-label="Permalink to &quot;💡 技术热情&quot;">​</a></h3><blockquote><p>&quot;业余时间会在知乎写技术博客，累计发布 30+ 篇文章。坚持参加线下 Laravel Meetup，保持技术敏感度。&quot;</p></blockquote><h3 id="💡-开源贡献" tabindex="-1">💡 开源贡献 <a class="header-anchor" href="#💡-开源贡献" aria-label="Permalink to &quot;💡 开源贡献&quot;">​</a></h3><blockquote><p>&quot;给某个 Laravel 扩展包提交过 PR，修复了它的一个小 Bug。虽然简单，但收获很大。&quot;</p></blockquote><h3 id="💡-认证资质" tabindex="-1">💡 认证资质 <a class="header-anchor" href="#💡-认证资质" aria-label="Permalink to &quot;💡 认证资质&quot;">​</a></h3><blockquote><p>&quot;考取了阿里云 ACA-PHP 认证和华为云 HCIA 认证，证明了基础功底。&quot;</p></blockquote><h3 id="💡-英语能力" tabindex="-1">💡 英语能力 <a class="header-anchor" href="#💡-英语能力" aria-label="Permalink to &quot;💡 英语能力&quot;">​</a></h3><blockquote><p>&quot;能流畅阅读英文文档和 Stack Overflow，偶尔参与国际开源社区讨论。&quot;</p></blockquote><h3 id="💡-产品思维" tabindex="-1">💡 产品思维 <a class="header-anchor" href="#💡-产品思维" aria-label="Permalink to &quot;💡 产品思维&quot;">​</a></h3><blockquote><p>&quot;我会和产品经理沟通，了解背后的业务逻辑，不仅仅是&#39;按需求写代码&#39;。&quot;</p></blockquote><hr><h2 id="避雷区" tabindex="-1">避雷区 <a class="header-anchor" href="#避雷区" aria-label="Permalink to &quot;避雷区&quot;">​</a></h2><h3 id="❌-过度吹嘘" tabindex="-1">❌ 过度吹嘘 <a class="header-anchor" href="#❌-过度吹嘘" aria-label="Permalink to &quot;❌ 过度吹嘘&quot;">​</a></h3><blockquote><p>&quot;整个系统都是我一个人写的&quot; —— 面试官会怀疑真实性</p></blockquote><h3 id="❌-贬低前东家" tabindex="-1">❌ 贬低前东家 <a class="header-anchor" href="#❌-贬低前东家" aria-label="Permalink to &quot;❌ 贬低前东家&quot;">​</a></h3><blockquote><p>&quot;领导水平太差、技术太落后&quot; —— 显得不专业</p></blockquote><h3 id="❌-过于冗长" tabindex="-1">❌ 过于冗长 <a class="header-anchor" href="#❌-过于冗长" aria-label="Permalink to &quot;❌ 过于冗长&quot;">​</a></h3><blockquote><p>超过 5 分钟的自我介绍会让人失去耐心</p></blockquote><h3 id="❌-背诵感太强" tabindex="-1">❌ 背诵感太强 <a class="header-anchor" href="#❌-背诵感太强" aria-label="Permalink to &quot;❌ 背诵感太强&quot;">​</a></h3><blockquote><p>自然交流比死记硬背更重要</p></blockquote><h3 id="❌-答非所问" tabindex="-1">❌ 答非所问 <a class="header-anchor" href="#❌-答非所问" aria-label="Permalink to &quot;❌ 答非所问&quot;">​</a></h3><blockquote><p>面试官问技术细节，不要扯业务话题</p></blockquote><hr><h2 id="实战演练建议" tabindex="-1">实战演练建议 <a class="header-anchor" href="#实战演练建议" aria-label="Permalink to &quot;实战演练建议&quot;">​</a></h2><h3 id="🎯-第-1-步-写好逐字稿" tabindex="-1">🎯 第 1 步：写好逐字稿 <a class="header-anchor" href="#🎯-第-1-步-写好逐字稿" aria-label="Permalink to &quot;🎯 第 1 步：写好逐字稿&quot;">​</a></h3><blockquote><p>把自我介绍写成文章，反复打磨</p></blockquote><h3 id="🎯-第-2-步-录音练习" tabindex="-1">🎯 第 2 步：录音练习 <a class="header-anchor" href="#🎯-第-2-步-录音练习" aria-label="Permalink to &quot;🎯 第 2 步：录音练习&quot;">​</a></h3><blockquote><p>听自己的录音，找语病和语速问题</p></blockquote><h3 id="🎯-第-3-步-模拟面试" tabindex="-1">🎯 第 3 步：模拟面试 <a class="header-anchor" href="#🎯-第-3-步-模拟面试" aria-label="Permalink to &quot;🎯 第 3 步：模拟面试&quot;">​</a></h3><blockquote><p>找朋友扮演面试官，进行压力测试</p></blockquote><h3 id="🎯-第-4-步-准备版本变体" tabindex="-1">🎯 第 4 步：准备版本变体 <a class="header-anchor" href="#🎯-第-4-步-准备版本变体" aria-label="Permalink to &quot;🎯 第 4 步：准备版本变体&quot;">​</a></h3><blockquote><p>1 分钟精简版 / 2 分钟标准版 / 3 分钟完整版</p></blockquote><h3 id="🎯-第-5-步-心理准备" tabindex="-1">🎯 第 5 步：心理准备 <a class="header-anchor" href="#🎯-第-5-步-心理准备" aria-label="Permalink to &quot;🎯 第 5 步：心理准备&quot;">​</a></h3><blockquote><p>自信表达，眼神交流，声音洪亮</p></blockquote><div class="tip custom-block"><p class="custom-block-title">最后提醒</p><p>自我介绍不是汇报简历，而是展示：</p><ul><li>✅ 沟通能力</li><li>✅ 逻辑思维</li><li>✅ 职业素养</li><li>✅ 自信心态</li></ul><p>把这当成第一次展现你的软实力机会！</p></div>`,138)])])}const q=s(l,[["render",t]]);export{b as __pageData,q as default};
